.p-dropdown {
    width: 100% !important;
}

.p-breadcrumb {
    border-radius: 0 !important;
}

div.p-selectbutton div.p-button {
   padding: 0.5rem 1rem !important;
}

// Printing a report: strip the app chrome so only the statement reaches paper.
// The `printing-report` class is added to <body> for the duration of the print
// dialog by the component that triggers it.
@media print {
    body.printing-report {
        navbar,
        side-nav,
        p-breadcrumb,
        .no-print {
            display: none !important;
        }

        // the reports shell keeps the content in a 10-of-12 column next to the
        // side nav; with the nav gone the statement should use the full page
        .col-10 {
            width: 100% !important;
        }

        .p-card,
        .p-card .p-card-body,
        .p-card .p-card-content {
            box-shadow: none !important;
            padding: 0 !important;
        }
    }
}
